import React, { useEffect, useState } from "react";
import './ProductCard.css';
import { Item } from "../../interfaces/product";

interface ProductCardProps {
    item: Item;
}

const ProductImage = () => {
    return (
        <div className="product-image-container">
            <div className="circle-container">
                <div style={{padding: "13px 9px", fontWeight: "500"}}>
                    <div>Product</div> 
                    <div>Image</div>
                </div>
            </div>
        </div>
    )
}

const ProductCard = ({item}: ProductCardProps) => {
    return (
        <div className="product-card">
            <ProductImage />
            <div className="center-text" style={{fontWeight: "Bold"}}>{item?.name}</div>
            <div className="center-text" style={{fontWeight: "Bold", marginBottom: "10px"}}>Price : ${item?.price}</div>
            <div className="product-details">
                <span>Total Reviews: </span>
                <span>{item?.totalreview}1</span>
            </div>

            <div className="product-details">
                <span>Rating: </span>
                <span>{item?.Rating}</span>
            </div>
        </div>
    );
};

export default ProductCard;
